    @staticmethod
    def resolve_url(root, _info: "ResolveInfo"):
        # check if URL is absolute:
        if urlparse(root.url).netloc:
            return root.url
        # unquote used for preventing double URL encoding
        return build_absolute_uri(default_storage.url(unquote(root.url)))


